import{_ as e,H as B,f as t,i as A}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"复习加餐 | 5组图读懂商业洞察！","description":"","frontmatter":{},"headers":[{"level":2,"title":"二维解构","slug":"二维解构","link":"#二维解构","children":[]},{"level":2,"title":"二八法则","slug":"二八法则","link":"#二八法则","children":[]},{"level":2,"title":"盐铁官营","slug":"盐铁官营","link":"#盐铁官营","children":[]},{"level":2,"title":"分层运营","slug":"分层运营","link":"#分层运营","children":[]},{"level":2,"title":"时间刻度","slug":"时间刻度","link":"#时间刻度","children":[]}],"relativePath":"商业思维案例笔记/复习加餐｜5组图读懂商业洞察！.md","filePath":"商业思维案例笔记/复习加餐｜5组图读懂商业洞察！.md","lastUpdated":1795554691000}'),i={name:"商业思维案例笔记/复习加餐｜5组图读懂商业洞察！.md"};function a(s,E,n,p,l,r){return B(),t("div",null,[...E[0]||(E[0]=[A('<h1 id="复习加餐-5组图读懂商业洞察" tabindex="-1">复习加餐 | 5组图读懂商业洞察！ <a class="header-anchor" href="#复习加餐-5组图读懂商业洞察" aria-label="Permalink to &quot;复习加餐 | 5组图读懂商业洞察！&quot;">​</a></h1><p>你好，我是晓蕾。</p><p>今天我们一起来复习一下“商业洞察”板块部分的内容。</p><p>还记得我们在导读说过什么是商业洞察力吗？所谓商业洞察力，就是要透过表象，看清楚行业各要素之间的结构关系，为产品和服务的优化找到可行的策略。有商业洞察力的人，可以直击业务本质，一针见血地找出问题并提出优化建议。</p><p>从这个板块开始，案例的体量就开始增加了，除去案例本身，曹老板也加入了一些社会现象的解读。不过不要紧，这次复习同样包含了思维导图和重点内容的图片，一张梳理思路，一张重点理解，绝对能让你的复习事半功倍。</p><p>好了，接下来就是你的时间了，快从从社区团购的案例开始复习吧！</p><h2 id="二维解构" tabindex="-1">二维解构 <a class="header-anchor" href="#二维解构" aria-label="Permalink to &quot;二维解构&quot;">​</a></h2><ul><li>冗长的供应链也是维系就业稳定民生的关键，在企业发展的基础上，一定要承担更多的社会责任和外部影响。</li></ul><p>问题分析：社区团购为什么成为 20 年巨头必争的赛道？</p><p>思维导图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/1.png" alt=""></a></p><p>重点卡片：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/2.jpeg" alt=""></a></p><p>推荐拓展阅读：《双周行业热点评论｜字节去肥增瘦，抖音爱奇艺联姻，每日优鲜破产》</p><h2 id="二八法则" tabindex="-1">二八法则 <a class="header-anchor" href="#二八法则" aria-label="Permalink to &quot;二八法则&quot;">​</a></h2><ul><li>80% 用户的 80% 需求，是高频产品需求，这类产品适合做广告变现。20% 用户 80% 的需求，是低频产品需求，这类产品适合做付费变现，前提是内容高质且独家。</li></ul><p>问题切入与分析回顾：为什么 Flipboard 等免费精品阅读领域做不大呢？</p><p>思维导图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/3.png" alt=""></a></p><p>重点卡片：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/4.jpeg" alt=""></a></p><p>推荐拓展阅读：</p><p>《会有小而美的事情发生吗》</p><h2 id="盐铁官营" tabindex="-1">盐铁官营 <a class="header-anchor" href="#盐铁官营" aria-label="Permalink to &quot;盐铁官营&quot;">​</a></h2><ul><li>厂商通过底层权限限制准入，把高收入、高利润的产业收归“国有”，从而实现高额利润。但是，如果硬件业务不行了，那相对应的互联网业务的变现天花板又在哪里呢？</li></ul><p>问题切入与分析回顾：手机厂商为什么可以在移动互联网时代闷声发大财？</p><p>思维导图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/5.png" alt=""></a></p><p>重点卡片：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/6.jpeg" alt=""></a></p><p>推荐拓展阅读：</p><p>《规则：豌豆荚做不起来应用内搜索？》</p><p>《边界：没有任何硬件基础的小米，为什么可以成为国内第一手机厂商？》</p><h2 id="分层运营" tabindex="-1">分层运营 <a class="header-anchor" href="#分层运营" aria-label="Permalink to &quot;分层运营&quot;">​</a></h2><ul><li>研究市场、形成认知、找到对手致命错误、给出解决方案。通过某种维度对市场、商家或者用户分层，实现收益最大化。任何同时拥有供给端和用户端的平台型业务都可以运用分层运营的思路。</li></ul><p>问题切入与分析回顾：为什么外卖市场上美团可以后发制人？</p><p>思维导图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/7.png" alt=""></a></p><p>重点卡片：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/8.jpeg" alt=""></a></p><p>推荐拓展阅读：</p><p>《资本（上）：为什么杨浩涌二次创业一定要融大钱？》（补贴相关）</p><h2 id="时间刻度" tabindex="-1">时间刻度 <a class="header-anchor" href="#时间刻度" aria-label="Permalink to &quot;时间刻度&quot;">​</a></h2><ul><li>时间刻度可以用来衡量广告业务的潜力空间。一般来说，长视频领域，会员模式的收入会高于广告模式的收入。但是，会员模式真的就可以解决一切问题了吗？</li></ul><p>问题切入与分析回顾：</p><p>为什么优酷土豆会从行业第一下滑到行业第三？（上）</p><p>为什么优酷土豆会从行业第一下滑到行业第三？（下）</p><p>思维导图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/9.png" alt=""></a></p><p>重点卡片：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/10.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%95%86%E4%B8%9A%E6%80%9D%E7%BB%B4%E6%A1%88%E4%BE%8B%E7%AC%94%E8%AE%B0/images/%25E5%25A4%258D%25E4%25B9%25A0%25E5%258A%25A0%25E9%25A4%2590-5%25E7%25BB%2584%25E5%259B%25BE%25E8%25AF%25BB%25E6%2587%2582%25E5%2595%2586%25E4%25B8%259A%25E6%25B4%259E%25E5%25AF%259F%25EF%25BC%2581/10.jpeg" alt=""></a></p><p>推荐拓展阅读：</p><p>《双周行业热点评论｜字节去肥增瘦，抖音爱奇艺联姻，每日优鲜破产》</p><p>最后，如果关于专栏，你有什么建议或更好的想法，也欢迎你分享在留言区，我一定会关注。</p><p>最后的最后，如果你觉得这门课对你有所帮助的话，欢迎你把课程分享给同事或朋友，我们共同学习进步！</p>',55)])])}const g=e(i,[["render",a]]);export{h as __pageData,g as default};
